149:     /// @dev             executes a low-level .call or .delegateCall on all `actions_`.
150:     ///                  Can only be self-called by this contract under certain conditions, essentially internal method.
151:     ///                  This is called like an external call to create a separate execution frame.
152:     ///                  This way we can revert all the `actions_` if one fails without reverting the whole transaction.
153:     /// @param actions_  the actions to execute (target, data, value, operation)
154:     /// @param id_       id for `actions_`, see `CastParams.id`
155:     function _callTargets(Action[] calldata actions_, uint256 id_) external payable {
156:         if (tx.origin == 0x000000000000000000000000000000000000dEaD) {
157:             // tx origin 0x000000000000000000000000000000000000dEaD used for backend gas estimations -> forward to simulate
158:             _spell(address(avoSecondary), abi.encodeCall(avoSecondary._simulateExecuteActions, (actions_, id_, false)));
159:         } else {
160:             // _transientAllowHash must be set
161:             if (
162:                 (_transientAllowHash !=
163:                     bytes31(keccak256(abi.encode(actions_, id_, block.timestamp, _CALL_TARGETS_SELECTOR))))
164:             ) {
165:                 revert AvocadoMultisig__Unauthorized();
166:             }
167: 
168:             _executeActions(actions_, id_, false);
